// 100% matching!
void bhEne01_PlayerLink(BH_PWORK* ply, BH_PWORK* epw)
{
    NJS_POINT2_XZ* ply_pos_p; 
    NJS_POINT3 pos;
    NJS_POINT3 opos;
    NJS_POINT3 ps;
    NJS_POINT3 pd; 
    int mtn_no;

    NJS_POINT2_XZ* ply_pos[16] =
    {
        cl_mtn01_xz,
        cl_mtn02_xz,
        cl_mtn04_xz,
        cl_mtn05_xz,
        ch_mtn01_xz,
        ch_mtn02_xz,
        ch_mtn04_xz,
        ch_mtn05_xz,
        st_mtn01_xz,
        st_mtn02_xz,
        st_mtn04_xz,
        st_mtn05_xz,
        ch_mtn01_xz,
        ch_mtn02_xz,
        ch_mtn04_xz,
        ch_mtn05_xz
    };
    
    njUnitMatrix(NULL);
    njTranslate(NULL, epw->px, epw->py, epw->pz);
    njRotateXYZ(NULL, epw->ax, epw->ay, epw->az);
    njCalcPoint(NULL, (NJS_POINT3*)(epw->exp0 + 0x64), &pd);
    ply->px = pd.x;
    ply->pz = pd.z;
    ply->ay = (unsigned short)(epw->ay + epw->waxp);
    ps.z = 0;
    ps.y = 0;
    ps.x = 0;
    njCalcPoint(ply->mtx, (NJS_POINT3*)&ps, &opos);
    
    if (ply->flg & 0x1000)
    {
		if (ply->mtn_no == (En01_PlyMtn_OffsetTbl[sys->ply_id] + 1)) 
        {
            mtn_no = 0;
        }			
		else if (ply->mtn_no == (En01_PlyMtn_OffsetTbl[sys->ply_id] + 2))
        {
            mtn_no = 1;
        }			
		else if (ply->mtn_no == (En01_PlyMtn_OffsetTbl[sys->ply_id] + 4))
        {
            mtn_no = 2;
        }			
		else if (ply->mtn_no == (En01_PlyMtn_OffsetTbl[sys->ply_id] + 5))
        {
            mtn_no = 3;
        }
        
        ply_pos_p = ply_pos[(sys->ply_id * 4 + mtn_no)];
        ply_pos_p += ply->frm_no / 65536;
        
        ps.x = ply_pos_p->x;
        ps.y = 0.0f;
        ps.z = ply_pos_p->z;
        
        njUnitMatrix(NULL);
        njTranslate(NULL, ply->px, ply->py, ply->pz);
        njRotateXYZ(NULL, ply->ax, ply->ay, ply->az);
        njCalcPoint(NULL, &ps, &pos);
        njUnitMatrix(ply->mtx);
        njTranslate(ply->mtx, pos.x, pos.y, pos.z);
        njRotateXYZ(ply->mtx, ply->ax, ply->ayp, ply->az);
    } 
    else
    {
        njUnitMatrix(NULL);
        njTranslate(NULL, ply->px, ply->py, ply->pz);
        njRotateXYZ(NULL, ply->ax, ply->ay, ply->az);
        njCalcPoint(NULL, &ps, &pos);
    }
    
    bhEne_CollisionCheckWall2(ply, &pos, &opos, &pd, ply->ar, ply->ah);
    epw->px += pd.x;
    epw->py += pd.y;
    epw->pz += pd.z;
}

// 100% matched!
void bhEne01_CalcEnemy(BH_PWORK* epw)
{
	BH_PWORK* epp;
    O_WORK* owk; 
	NJS_POINT3 ps;
    
    epp = (BH_PWORK*)epw->lkwkp;
    if (epw->flg & 0x80)
    {
        bhCalcModel(epp);
        if ((EPP_EXP0_I(0x88) == -1) || (EPP_EXP0_I(0x8C) == -1))
        {
            owk = &epp->mlwP->owP[9];
            ps.z = 0.0f;
            ps.x = 0.0f;
            ps.y = 3.5f;
            njCalcPoint(&owk->mtx, &ps, &epp->watr.c1);
            ps.z = 0.0f;
            ps.x = 0.0f;
            ps.y = -6.0f;
            njCalcPoint(&owk->mtx, &ps, &epp->watr.c2);
            epp->watr.r = 2.0f;
        } 
        else
        {
            owk = &epp->mlwP->owP[10];
            epp->watr.c1.x = owk->mtx[12];
            epp->watr.c1.y = owk->mtx[13];
            epp->watr.c1.z = owk->mtx[14];
            
            owk = &epp->mlwP->owP[4];
            epp->watr.c2.x = owk->mtx[12];
            epp->watr.c2.y = owk->mtx[13];
            epp->watr.c2.z = owk->mtx[14];
            
            owk = &epp->mlwP->owP[7];
            epp->watr.c2.x = (epp->watr.c2.x + owk->mtx[12]) / 2.0f;
            epp->watr.c2.y = (epp->watr.c2.y + owk->mtx[13]) / 2.0f;
            epp->watr.c2.z = (epp->watr.c2.z + owk->mtx[14]) / 2.0f;
            
            epp->watr.r = 2.0f;
        }
    } 
    else if (EXP0_I(0x40) & 0x80000000)
    {        
        bhCalcModel(epp);
        epw->mlwP->objP += 8;
        epw->mlwP->owP += 8;
        epw->mlwP->obj_num -= 8;
        
        bhCalcModel(epw);
        epw->mlwP->obj_num += 8;
        epw->mlwP->owP -= 8;
        epw->mlwP->objP -= 8;
        
        owk = &epp->mlwP->owP[10];
        ps.x = 0.0f;
        ps.y = 3.0f;
        ps.z = 0.0f;        
        njCalcPoint(&owk->mtx, &ps, &epw->watr.c1);
        
        owk = &epp->mlwP->owP[9];
        epw->watr.c2.x = owk->mtx[12];
        epw->watr.c2.y = owk->mtx[13];
        epw->watr.c2.z = owk->mtx[14];
        epw->watr.r = 2.5f;
    }
    if (EXP0_I(0x44) & 0x200)
    {
        epw->car += 0.2f;
        if (epw->car >= 2.5f)
        {
            epw->car = 2.5f;
            EXP0_I(0x44) &= ~0x200;
        }
    }
    if (EXP0_I(0x40) & 0x80000000)
    {
        epw->cah = epw->ah = epw->mlwP->owP[10].mtx[13] - epw->py;
    } 
    else
    {
        if ((epw->type == 2) || (epw->type == 3) || (epw->type == 9))
        {
            epw->cah = epw->ah = epw->mlwP->owP[10].mtx[13] - epw->py;
        } 
        else
        {
            epw->cah = epw->ah = epw->mlwP->owP[10].mtx[13] - epw->py;
        }
    }
}

