// 100% matching!
void bhEne01_CollCheck(BH_PWORK* epw) 
{
    BH_PWORK* epp, *ep; 
    O_WORK* owk; 
    ATR_WORK* hp; 

    epp = (BH_PWORK*)epw->lkwkp;

    if ((EXP0_I(64) & 0x80000000))
    {
        ep = ((epw->flg & 0x80)) ? epp : epw;
        
        if (!(ep->flg & 0x2)) 
        {
            if ((ep->flg & 0x8)) 
            { 
                if ((EP_EXP0_I(64) & 0x100)) 
                {
                    bhEne01_CollCheckPush(ep, ene);
                } 
                else 
                {
                    if ((epw->flg & 0x80))
                    {
                        owk = ep->mlwP->owP;
                        
                        ep->aox = owk->mtx[12] - ep->px;
                        ep->aoz = owk->mtx[14] - ep->pz;
                        ep->aoy = 0;
                    }
                    else 
                    {
                        ep->aox = 0;
                        ep->aoy = 0;
                        ep->aoz = 0;
                    }
                    
                    if (!(EP_EXP0_I(64) & 0x40))
                    {
                        if ((EP_EXP0_I(64) & 0x40000)) 
                        {
                            ep->flg2 &= ~0x1;
                            
                            bhCheckPlayer(ep);
                            
                            ep->flg2 |= 0x1;
                        }
                        else 
                        {
                            bhCheckPlayer(ep);
                        }
                        
                        bhCheckEnemies(ep);
                    }
                }
            }
            
            bhEne01_CollCheckWall(ep);
        }
    } 
    else if ((!(epw->flg & 0x2)) && ((EXP0_I(64) & 0x40000000))) 
    {
        bhEne01_CollCheckWall(epw);
    }
    else if ((sys->st_flg & 0x100)) 
    {
        epw->mdflg &= ~0x40;
        
        hp = bhCheckFloorEffect(epw->flr_no, epw->px, epw->pz);
        
        if ((hp != NULL) && (hp->prm0 == 2)) 
        {
            epw->mdflg |= 0x40;
        }
    }
    
    if ((((sys->st_flg & 0x40)) && (!(epw->stflg & 0x100000))) && (bhCheckWater((NJS_POINT3*)&epw->px) != NULL)) 
    {
        epw->stflg |= 0x100000;
    }
}

// 100% matching!
void bhEne01_CollCheckPush(BH_PWORK* epw, BH_PWORK* top_epw)
{
	float x;
	float y;
	float z;
 	int i;   
	int whit;
	int fhit;
    BH_PWORK* ep;

    ep = top_epw;
    for (i = 0; i < sys->ewk_n; i++, ep++)
    {
        if ((ep->flg & 1) && !(ep->flg & 0x80))
        {
            ep->stflg &= ~2;
        }
    }

    bhCheckPlayer(epw);
    x = epw->px;
    y = epw->py;
    z = epw->pz;
    bhCheckEnemies(epw);
    whit = 0;

    ep = top_epw;
    for (i = 0; i < sys->ewk_n; i++, ep++)
    {
        if (ep->id == 1 || ep->id == 26)
        {              
            if ((ep->flg & 1) && !(ep->flg & 2) && !(ep->flg & 0x80) && (ep != epw))
            {
                if ((ep->type != 2) && (ep->type != 3) && (ep->type != 6) && (ep->type != 7) && (ep->type != 9) && (ep->type != 10) && (ep->mode0 == 1))
                {
                    if (ep->exp0 != NULL)
                    {                       
                        if (!(EP_EXP0_I(0x40) & 0x400000) && !(EP_EXP0_I(0x40) & 0x40000) && !(EP_EXP0_I(0x40) & 0x200))
                        {
                            if (ep->stflg & 2)
                            {
                                EP_EXP0_I(0x40) |= 0x200;
                                if (bhCdirCheck((unsigned short)(epw->ay + NJM_DEG_ANG(180.0f)), ep->ay) == 0)
                                {
                                    fhit = 1;
                                    EP_EXP0_I(0x40) |= 0x2000;
                                } 
                                else
                                {
                                    fhit = 0;
                                    EP_EXP0_I(0x40) &= ~0x2000;
                                }

                                if (bhEne01_EnemyHitChk(epw, ep, 5461) != 0)
                                {
                                    ep->dvx = -njSin(ep->ay);
                                    ep->dvz = -njCos(ep->ay);
                                    ep->dvy = 0.0f;
                                    
                                    if (ep->id == 26)
                                    {
                                        ep->mode2 = 2;
                                    } 
                                    else
                                    {
                                        if (fhit == 0)
                                        {
                                            ep->mode2 = 3;
                                        } 
                                        else
                                        {
                                            ep->mode2 = 4;
                                        }
                                    }
                                } 
                                else
                                {
                                    ep->mode2 = 2;
                                }
                                
                                ep->mode0 = 3;
                                ep->mode1 = 0;
                                ep->mode3 = 0;

                                if (epw->exp1 != NULL)
                                {
                                    EPW_EXP1_UC(0xC) = 3;
                                }
                            }
                            if (ep->stflg & 1)
                            {
                                whit = 1;
                            }
                        }
                    }
                }
            }            
        }
    }
    if (whit == 0)
    {
        epw->px = x;
        epw->py = y;
        epw->pz = z;
    }
}

// 98.81% matching!
int bhEne01_EnemyHitChk(BH_PWORK* epw, BH_PWORK* tepw, int rng)
{
	int ang;
	int r2;

    ang = (unsigned short)NitenDir_ck(tepw->px, tepw->pz, epw->px, epw->pz);
    ang = (unsigned short)(tepw->ay + ang);
    r2 = (unsigned short)(tepw->ay - rng);


    if (!((unsigned short)(tepw->ay + rng) < ang)
        || !((unsigned short)(ang < r2)))
    {
        return 1;
    } 
    else
    {
        return 0;
    }
}

