// 100% matching!
void bhEne01_EneSearch(BH_PWORK* epw)
{
    NJS_CNK_OBJECT* neck_obj;
    O_WORK* neck_owk;
    NJS_POINT3 pos;

    neck_owk = &epw->mlwP->owP[11];
    neck_obj = &epw->mlwP->objP[11];

    pos.x = neck_owk->mtx[12];
    pos.y = 0.0f;
    pos.z = neck_owk->mtx[14];

    if ((EXP0_UC(0x28) & 0x1F) < 31)
    {
        if (bhSearchPlayer2(epw, &pos, epw->ay + neck_obj->ang[1], en01_PersonalType[EXP0_I(0x4C)].ang) != -1)
        {
            EXP0_UC(0x28) |= 0x20;
        }
        
        if (EXP0_UC(0x28) & 0x20)
        {
            EXP0_UC(0x28) |= 0x40;
            EXP0_UC(0x28) &= ~0x20;
        } 
        else if ((EXP0_UC(0x28) & 0x1F) == 30)
        {
            EXP0_UC(0x28) &= ~0x40;
        }
    }
    
    EXP0_UC(0x28)++;
    if ((EXP0_UC(0x28) & 0x1F) >= 31)
    {
        EXP0_UC(0x28) &= ~0x1F;
    }

    if (EXP0_UC(0x28) & 0x40)
    {
        EXP0_I(0x40) |= 0x400;
        EXP0_UC(0x29) = 15;
    }    
    else if (EXP0_I(0x40) & 0x400)
    {
        if (--EXP0_UC(0x29) < 0)
        {
            EXP0_I(0x40) &= ~0x400;
        }
    }
}

// 100% matching!
void bhEne01_Brain00(BH_PWORK* epw)
{
    NJS_POINT3 pos;
    unsigned char RutID;

    bhEne01_EneSearch(epw);
    if (epw->type != 5)
    {
        if (EXP0_I(0x40) & 0x400)
        {
            if ((EXP0_F(0x54) < 50.0f) && (EXP0_I(0x70) == 0) && (epw->flr_no == plp->flr_no))
            {
                EXP0_F(0x58) = plp->px;
                EXP0_F(0x60) = plp->pz;
                EXP0_UC(0x2A) = bhCheckRouteID((NJS_POINT3*)&epw->px);
                EXP0_UC(0x2B) = 0;             
            } 
            else
            {
                RutID = (unsigned char) bhCheckRouteID((NJS_POINT3*)&epw->px);
                EXP0_UC(0x2B)++;
                if ((EXP0_UC(0x2A) == RutID) || (EXP0_UC(0x2B) >= 255))
                {
                    RutID = bhCheckRoute((NJS_POINT3*)&epw->px, (NJS_POINT3*)&plp->px, &pos);
                    EXP0_F(0x58) = pos.x;
                    EXP0_F(0x60) = pos.z;
                    EXP0_UC(0x2A) = RutID;
                    EXP0_UC(0x2B) = 0;
                }
            }            
        }
    } 
    else
    {
        RutID = bhCheckRoute((NJS_POINT3*)&epw->px, (NJS_POINT3*)&plp->px, &pos);
        EXP0_F(0x58) = pos.x;
        EXP0_F(0x60) = pos.z;
        EXP0_UC(0x2A) = RutID;
        EXP0_UC(0x2B) = 0;
    }
    
    if (bhEne01_KaidanCheck(epw) != 0)
    {
        if (!(epw->flg & 0x200000))
        {
            epw->mode1 = 0;
            epw->mode2 = 8;
            epw->mode3 = 0;
            EXP0_I(0x40) |= 0x400000;
            return;
        }
        EXP0_I(0x40) &= ~0x400;
        bhClrUseKaidanFlag(epw);
    }
}


