int bhEne01_EatCheck(BH_PWORK* epw, int rng, float dist, int mode)
{
    NJS_SPHERE at;
    O_WORK* owk;
    NJS_POINT3 ps;
    NJS_POINT3 eps;
    float ds;

    if ((EXP0_I(0x40) & 0x20000000) || (plp->flg & 2) || (plp->stflg & 0x80000000))
    {
        return 0;
    }
    
    owk = &plp->mlwP->owP[3];
    ps.x = owk->mtx[12];
    ps.y = plp->py;
    ps.z = owk->mtx[14];
    owk = &epw->mlwP->owP[10];
    eps.x = owk->mtx[12];
    eps.y = plp->py;
    eps.z = owk->mtx[14];

    ds = njDistanceP2P(&ps, &eps);

    switch (mode)
    {
    case 0:
        if ((bhSearchPlayer2(epw, &eps, epw->ay, rng) == -1) ||
            (ds >= dist) ||
            (plp->py != epw->py) ||
            (plp->hp < 0))
        {
            break;
        }
            
        return 1;

    case 1:
        if ((plp->py != epw->py) || (plp->hp < 0))
        {
            break;
        }
        
        return 1;

    case 2:
        owk = &epw->mlwP->owP[10];
        ps.x = 0.0f;
        ps.y = 0.0f;
        ps.z = -4.0f;
        njCalcPoint((NJS_MATRIX*)owk->mtx, &ps, &at.c);
        at.r = 1.0f;

        if (!npCollisionCheckSC(&at, &plp->watr) ||
           (plp->py != epw->py) ||
           (plp->flg & 2) ||
           (plp->stflg & 0x80000000) ||
           (plp->hp < 0))
        {
            break;            
        }
        return 1;
       
    }
    return 0;
}

